package net.minecraft.world.item;import java.util.*;import net.minecraft.world.entity.EquipmentSlot;public class ItemStack{public static final ItemStack EMPTY=new ItemStack("minecraft:air",0);public String id;public int count,damage;public Map<Object,Object> components=new HashMap<>();public ItemStack(String id,int n){this.id=id;count=n;}public ItemStack copy(){ItemStack n=new ItemStack(id,count);n.components.putAll(components);n.damage=damage;return n;}public ItemStack copyWithCount(int c){ItemStack s=copy();s.count=c;return s;}public String getItem(){return id;}public int getCount(){return count;}public void setCount(int n){count=n;}public boolean isEmpty(){return count<=0||id.equals("minecraft:air");}public void shrink(int n){count=Math.max(0,count-n);}public void grow(int n){count+=n;}public int getMaxStackSize(){return 64;}public int getDamageValue(){return damage;}public void setDamageValue(int n){damage=n;}public Object set(Object k,Object v){return components.put(k,v);}public static boolean isSameItemSameComponents(ItemStack a,ItemStack b){return a.id.equals(b.id)&&a.components.equals(b.components);}public boolean canEquip(EquipmentSlot slot,Object n){return id.endsWith(slot==EquipmentSlot.HEAD?"_helmet":slot==EquipmentSlot.CHEST?"_chestplate":slot==EquipmentSlot.LEGS?"_leggings":"_boots");}}